import asyncio

async def act(page):
    # Use filter_pages_by_content_type to get links from the current page
    filtered_links = await filter_pages_by_content_type(page, page_url="/?p=8")

    # Define which content types might contain the Archives widget (e.g., category, tag, author, post, page)
    relevant_types = ['category', 'tag', 'author', 'post', 'page']

    # Collect URLs from relevant types
    urls_to_visit = []
    for content_type in relevant_types:
        if content_type in filtered_links:
            for link_info in filtered_links[content_type]:
                urls_to_visit.append(link_info['url'])

    # Also include the homepage if present
    if 'homepage' in filtered_links:
        for link_info in filtered_links['homepage']:
            urls_to_visit.append(link_info['url'])

    # Remove duplicates
    urls_to_visit = list(set(urls_to_visit))

    # Iterate through each URL to search for the Archives widget
    for url in urls_to_visit:
        # Navigate to this page
        await page.goto(url)
        await page.wait_for_load_state('load')
        await asyncio.sleep(2)  # Wait for dynamic content

        # Search for the 'Archives' widget using common roles
        archives_widget = None
        # Try complementary, region, group roles with name containing 'Archives'
        try:
            archives_widget = page.get_by_role("complementary", name="Archives")
        except:
            pass
        if not archives_widget or await archives_widget.count() == 0:
            try:
                archives_widget = page.get_by_role("region", name="Archives")
            except:
                pass
        if not archives_widget or await archives_widget.count() == 0:
            try:
                archives_widget = page.get_by_role("group", name="Archives")
            except:
                pass

        # If Archives widget is found, look for the 'December 2017' link within it
        if archives_widget and await archives_widget.count() > 0:
            december_link = archives_widget.get_by_role("link", name="December 2017")
            if await december_link.count() > 0:
                await december_link.click(timeout=10000)
                await page.wait_for_load_state('load')
                # Task completed: clicked the link
                return
    # If loop completes without finding, return a message
    return "Archives widget or December 2017 link not found on filtered pages."

